    (C spa lo shi ff fp : Z) (LF : list fframe) (m mx : mem) (gap : list cell) (p8 lj hj sh32 : list byte) (bflag : byte),
  rw_cells asegs mx spa [CB 8 p8; C8 (Z_to_bv 64 ff); CB 24 lj] -> lo <= spa ->
  rw_cells asegs mx (spa + 40) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -88 - (spa + 40) ->
